%%%%%%%%%%% 区域 - 弯曲扇形
M=128;
start_angle = 0;            % 起始角度 (弧度)
end_angle = pi;           % 终止角度 (弧度)，这里为90度，可调整

y = linspace(start_angle, end_angle, M+1);  % 角度范围

% 弯曲边界（由 mtheta 定义）
mtheta = exp(cos(y))-cos(12.*y)+1.5.*sin(y./2).^5;
xx = mtheta .* cos(y);
yy = mtheta .* sin(y);

% 两条半径（从原点到边界两端）
x_radius1 = [0, mtheta(1)*cos(start_angle)];
y_radius1 = [0, mtheta(1)*sin(start_angle)];
x_radius2 = [0, mtheta(end)*cos(end_angle)];
y_radius2 = [0, mtheta(end)*sin(end_angle)];

figure, 
plot(xx, yy, 'b-', 'LineWidth', 4), hold on;
plot(x_radius1, y_radius1, 'b-', 'LineWidth', 4);
plot(x_radius2, y_radius2, 'b-', 'LineWidth', 4);

axis([-4 4 0 2.5]);
xlabel('x'), ylabel('y'); 
grid on; 
set(gca, 'FontSize', 18, 'XTick', [-4 -2   0  2 4 ], 'YTick', [0  0.5 1 1.5  2 2.5]);
axis equal;
grid on;
set(gca, 'GridLineStyle', ':', 'GridColor', 'k', 'GridAlpha', 0.5);
%%%%%%%%%%% 区域
%%%%%%%%%%% 画真解
 %%==================== 13. 绘制真解图像 ====================
% 在物理区域上绘制真解
M_plot = 200;  % 角度方向采样点数
N_plot = 100;  % 径向采样点数

% 生成物理坐标网格
y_plot = linspace(ya, yb, M_plot);
r_plot = linspace(0, 1, N_plot);
[Y_plot, R_plot] = meshgrid(y_plot, r_plot);

% 计算边界形状
mtheta_plot = exp(cos(y_plot))-cos(12.*y_plot)+1.5.*sin(y_plot./2).^5;
% 物理坐标: x = r * mtheta * cos(theta), y = r * mtheta * sin(theta)
X_phys = R_plot .* mtheta_plot .* cos(Y_plot);
Y_phys = R_plot .* mtheta_plot .* sin(Y_plot);

% 计算真解值
U_exact = uxy(X_phys, Y_phys);

% 绘制真解
figure('Position', [100, 100, 650, 550]);

% 使用pcolor绘制彩色填充图
pcolor(X_phys, Y_phys, U_exact);
shading interp;  % 平滑插值，去掉网格线
axis([-4 4 0 2.5]);
xlabel('x', 'FontSize', 14);
ylabel('y', 'FontSize', 14);
% ===== 添加颜色条（右侧的彩色坐标图） =====
colorbar('FontSize', 12);
% 可以设置颜色条的标签
% colorbar('FontSize', 12, 'Ticks', linspace(min(U_exact(:)), max(U_exact(:)), 11));

% 选择配色方案
%colormap(jet);  % 彩虹色
% colormap(turbo);   % 鲜艳彩虹色
% colormap(parula);  % MATLAB默认
% colormap(hot);     % 热力图
colormap(winter);
axis([-4 4 0 2.5]);
set(gca, 'FontSize', 14);
grid on;
set(gca, 'GridLineStyle', ':', 'GridAlpha', 0.2);
